    case '*':
      return true;
    case 'A':
      return !molecule.aromatic;
    case 'a':
      return molecule.aromatic;
  }
  return pattern.choices.any(
    (c) => c.symbol == molecule.symbol && c.aromatic == molecule.aromatic,
  );
}

