int gcd(int a, int b) {
  while (b != 0) {
    final r = a % b;
    a = b;
    b = r;
  }
  return a;
}

Fraction fraction(int n, int d) {
  final g = gcd(n, d);
  return Fraction(n ~/ g, d ~/ g);
}

class Similarity {
