    if (i + 1 < content.length &&
        content[i + 1].compareTo('a') >= 0 &&
        content[i + 1].compareTo('z') <= 0 &&
        elements.containsKey(content.substring(i, i + 2))) {
      symbol = content.substring(i, i + 2);
